ValidationRule.errorConditionFormula:
AND(
      /* Exclude Record Types */
    NOT(
    OR(
         RecordType.DeveloperName = "DairyWorkerLicence",
         RecordType.DeveloperName = "PHOCSBCCDCDairyPlantLicence"
      )
      ),
    NOT(ISBLANK(AccountId)),
    NOT(ISBLANK(LicenseTypeId)),

    OR(
        TEXT(Account.Type) = "Industrial Camps",
        TEXT(Account.Type) = "Personal Services"
    ),

    NOT(
        OR(

            AND(
                Account.RecordTypeName__c = "Facility",
                TEXT(Account.Type) = "Industrial Camps",
                OR(
                    RecordType.DeveloperName = "OperatingPermitApplication",
                    RecordType.DeveloperName = "PHOCSExemptions"
                ),
                OR(
                    LicenseType.Name = "Industrial Camp Operating Permit",
                    LicenseType.Name = "Industrial Camp Sewerage System of Approval"
                )
            ),

            AND(
                Account.RecordTypeName__c = "Facility",
                TEXT(Account.Type) = "Personal Services",
                OR(
                    RecordType.DeveloperName = "OperatingPermitApplication",
                    RecordType.DeveloperName = "PHOCSExemptions"
                ),
                OR(
                    LicenseType.Name = "Personal Service Establishment Health Approval",
                    LicenseType.Name = "Temporary Personal Service Establishment Health Approval"
                )
            )
        )
    )
)
